#include <bits/stdc++.h>
using namespace std;

struct Point {
    double x, y;
    Point(double x_=0, double y_=0): x(x_), y(y_) {}
    Point add(const Point& o) const { return Point(x + o.x, y + o.y); }
    Point sub(const Point& o) const { return Point(x - o.x, y - o.y); }
    Point rotate(double a) const {
        double c = cos(a), s = sin(a);
        return Point(x * c - y * s, x * s + y * c);
    }
    Point norm() const {
        double len = length();
        if (len < 1e-8) return Point(0, 0);
        return scale(1.0 / len);
    }
    Point scale(double f) const { return Point(x * f, y * f); }
    double length() const { return hypot(x, y); }
    bool equals(const Point& o) const {
        return std::abs(x - o.x) < 1e-8 && std::abs(y - o.y) < 1e-8;
    }
    int compareTo(const Point& o) const {
        if (std::abs(x - o.x) > 1e-8) return (x < o.x) ? -1 : 1;
        if (std::abs(y - o.y) > 1e-8) return (y < o.y) ? -1 : 1;
        return 0;
    }
    string toString() const {
        char buf[64];
        snprintf(buf, sizeof(buf), "%.6f %.6f", x, y);
        return string(buf);
    }
};

struct Circle {
    Point o;
    double r;
    Circle(Point o_=Point(), double r_=0): o(o_), r(r_) {}
    bool contains(const Point& p) const {
        return std::abs(p.sub(o).length() - r) < 1e-8;
    }
};

vector<Point> circleIntersections(const Circle& c1, const Circle& c2) {
    double dx = c1.o.x - c2.o.x;
    double dy = c1.o.y - c2.o.y;
    double d = hypot(dx, dy);
    double cosA = (c1.r * c1.r + d * d - c2.r * c2.r) / (2 * c1.r * d);
    if (cosA < -1 - 1e-8 || cosA > 1 + 1e-8) return {};
    if (cosA < -1) cosA = -1;
    if (cosA > 1) cosA = 1;
    double alpha = acos(cosA);
    Point dir = Point(dx, dy).norm();
    vector<Point> res;
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(+alpha)));
    res.push_back(c1.o.add(dir.scale(c1.r).rotate(-alpha)));
    return res;
}

void dfs(int u, vector<bool>& visited, const vector<set<int>>& adj) {
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v]) dfs(v, visited, adj);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; cin >> n;
    vector<Circle> circles(n);
    for (int i=0; i<n; i++) {
        int x, y, r; cin >> x >> y >> r;
        circles[i] = Circle(Point(x,y), r);
    }

    set<Point> points;
    for (int i=0; i<n; i++) {
        for (int j=i+1; j<n; j++) {
            auto inters = circleIntersections(circles[i], circles[j]);
            for (auto& p : inters) {
                points.insert(p);
            }
        }
    }

    map<Point,int> pointIds;
    vector<set<int>> adj;
    auto assignPoint = [&](const Point& p) {
        if (pointIds.count(p) == 0) {
            int id = (int)pointIds.size();
            pointIds[p] = id;
            adj.emplace_back();
        }
    };

    for (int i=0; i<n; i++) {
        vector<double> angles;
        for (int j=0; j<100; j++) {
            angles.push_back(2 * M_PI * j / 100);
        }
        for (const auto& p : points) {
            if (circles[i].contains(p)) {
                double dx = p.x - circles[i].o.x;
                double dy = p.y - circles[i].o.y;
                double a = atan2(dy, dx);
                if (a < 0) a += 2 * M_PI;
                angles.push_back(a);
            }
        }
        sort(angles.begin(), angles.end());
        Point dir = Point(1, 0).scale(circles[i].r);
        vector<double> sortedAngles = angles;
        // Remove duplicates considering EPS
        vector<double> uniqueAngles;
        for (size_t j=0; j<sortedAngles.size(); j++) {
            if (j==0 || std::abs(sortedAngles[j] - sortedAngles[j-1]) > 1e-8) {
                uniqueAngles.push_back(sortedAngles[j]);
            }
        }
        for (double a : uniqueAngles) {
            Point p = circles[i].o.add(dir.rotate(a));
            assignPoint(p);
        }
        int sz = (int)uniqueAngles.size();
        for (int j=0; j<sz; j++) {
            Point p1 = circles[i].o.add(dir.rotate(uniqueAngles[j]));
            Point p2 = circles[i].o.add(dir.rotate(uniqueAngles[(j+1)%sz]));
            int u = pointIds[p1];
            int v = pointIds[p2];
            if (u != v) {
                adj[u].insert(v);
                adj[v].insert(u);
            }
        }
    }

    int vCount = (int)pointIds.size();
    int eCount = 0;
    for (const auto& neighbors : adj) {
        eCount += (int)neighbors.size();
    }
    eCount /= 2;

    int components = 0;
    vector<bool> visited(vCount, false);
    for (int i=0; i<vCount; i++) {
        if (!visited[i]) {
            components++;
            dfs(i, visited, adj);
        }
    }

    cout << 1 + components + eCount - vCount << "\n";

    return 0;
